package com.gaeul.allin;
import org.json.*;
import java.util.*;
public class DeepSeekToolBridgeTest {
 static void review(DeepSeekToolBridge.Prepared p, JSONObject req) throws Exception {
  int failures=0;
  for(int k=0;k<4;k++) try { reviewCase(k,p,req); } catch(AssertionError e) {System.err.println("review failure "+k); failures++;}
  if(failures>0)throw new AssertionError(failures+" review cases failed");
 }
 static void reviewCase(int k,DeepSeekToolBridge.Prepared p,JSONObject req)throws Exception {
  if(k==0){String prompt=p.buildPrompt();check(prompt.contains("\"id\":\"c1\"") && prompt.contains("Tool result (run, id=c1): done"));}
  if(k==1){for(String fence:new String[]{"","```json\n"}){String input="before<tool_call>"+fence+"{\"name\":\"run\",\"arguments\":{\"x\":\"</tool_call> and \\\"q\\\"\"}}"+(fence.isEmpty()?"":"\n```")+"</tool_call>after";for(int split=0;split<=input.length();split++){Sink s=new Sink();DeepSeekToolBridge.StreamParser parser=p.newParser(s);parser.feed(input.substring(0,split));parser.feed(input.substring(split));check(parser.finish().size()==1);check(s.text.toString().equals("beforeafter"));check(new JSONObject(s.calls.get(0).arguments).getString("x").contains("</tool_call>"));}Sink chars=new Sink();DeepSeekToolBridge.StreamParser each=p.newParser(chars);for(int i=0;i<input.length();i++)each.feed(input.substring(i,i+1));check(each.finish().size()==1&&chars.text.toString().equals("beforeafter"));}}
  if(k==2){String[] attrs={"string=\"true\"","string=\"false\"","string=\"false\""};String[] values={"123","[1,2]","not-json"};for(int i=0;i<3;i++){String input="<｜｜DSML｜｜ calls><｜｜DSML｜｜ invoke name=\"run\"><｜｜DSML｜｜ parameter name=\"x\" "+attrs[i]+">"+values[i]+"</｜｜DSML｜｜ parameter></｜｜DSML｜｜ invoke></｜｜DSML｜｜ calls>";Sink sink=new Sink();DeepSeekToolBridge.StreamParser parser=p.newParser(sink);parser.feed(input);List<DeepSeekToolBridge.ToolCall> calls=parser.finish();if(i==2)check(calls.isEmpty()&&sink.text.toString().equals(input));else {check(calls.size()==1);Object value=new JSONObject(calls.get(0).arguments).get("x");check(i==0?value instanceof String:value instanceof JSONArray);}}}
  if(k==3){JSONObject bad=new JSONObject(req.toString());bad.getJSONArray("messages").getJSONObject(1).getJSONArray("tool_calls").getJSONObject(0).getJSONObject("function").put("arguments","{bad");try{DeepSeekToolBridge.analyze(bad);throw new AssertionError();}catch(IllegalArgumentException expected){} JSONObject duplicate=new JSONObject(req.toString());JSONArray calls=duplicate.getJSONArray("messages").getJSONObject(1).getJSONArray("tool_calls");calls.put(new JSONObject(calls.getJSONObject(0).toString()));try{DeepSeekToolBridge.analyze(duplicate);throw new AssertionError();}catch(IllegalArgumentException expected){}}
 }
 static void check(boolean b){if(!b)throw new AssertionError();}
 static class Sink implements DeepSeekToolBridge.Listener {StringBuilder text=new StringBuilder(); List<DeepSeekToolBridge.ToolCall> calls=new ArrayList<>(); public void onText(String s){text.append(s);} public void onToolCall(DeepSeekToolBridge.ToolCall c){calls.add(c);}}
 public static void main(String[] x)throws Exception {
  JSONObject req=new JSONObject("{\"messages\":[{\"role\":\"user\",\"content\":\"hi\"},{\"role\":\"assistant\",\"tool_calls\":[{\"id\":\"c1\",\"function\":{\"name\":\"run\",\"arguments\":\"{\\\"x\\\":1}\"}}]},{\"role\":\"tool\",\"tool_call_id\":\"c1\",\"content\":\"done\"}],\"tools\":[{\"type\":\"function\",\"function\":{\"name\":\"run\",\"parameters\":{\"type\":\"object\"}}}]}");
  DeepSeekToolBridge.Prepared p=DeepSeekToolBridge.analyze(req); String prompt=p.buildPrompt(); check(p.enabled && prompt.contains("[Tool calling]") && prompt.contains("Tool result (run, id=c1): done") && prompt.contains("<tool_call>"));
  String ds="<｜｜DSML｜｜ calls><｜｜DSML｜｜ invoke name=\"run\"><｜｜DSML｜｜ parameter name=\"cmd\" string=\"true\">ls -la \"a > b\"</｜｜DSML｜｜ parameter></｜｜DSML｜｜ invoke></｜｜DSML｜｜ calls>";
  String input="前<tool_call>{\"name\":\"run\",\"arguments\":{\"x\":1}}</tool_call>中"+ds+"后";
  for(int split=0;split<=input.length();split++){Sink s=new Sink(); DeepSeekToolBridge.StreamParser parser=p.newParser(s); parser.feed(input.substring(0,split));parser.feed(input.substring(split));check(parser.finish().size()==2);check(s.text.toString().equals("前中后"));check(s.calls.get(0).arguments.equals("{\"x\":1}") && !s.calls.get(0).id.equals(s.calls.get(1).id));check(new JSONObject(s.calls.get(1).arguments).getString("cmd").equals("ls -la \"a > b\""));}
  Sink s=new Sink(); DeepSeekToolBridge.StreamParser parser=p.newParser(s);String bad="A<tool_call>{\"name\":\"run\",\"arguments\":[]}</tool_call>B<tool_call>{\"name\":\"evil\",\"arguments\":{}}</tool_call>C<tool_call>{\"name\":\"run\""; parser.feed(bad);check(parser.finish().isEmpty());check(s.text.toString().equals(bad));
  for(String choice:new String[]{"required","garbage"}) {try {DeepSeekToolBridge.analyze(new JSONObject(req.toString()).put("tool_choice",choice));throw new AssertionError();}catch(IllegalArgumentException expected){}}
  check(!DeepSeekToolBridge.analyze(new JSONObject(req.toString()).put("tool_choice","none")).enabled);check(!DeepSeekToolBridge.analyze(new JSONObject().put("tools",new JSONArray())).enabled);
  Sink charSink=new Sink(); DeepSeekToolBridge.StreamParser charParser=p.newParser(charSink); for(int i=0;i<input.length();i++)charParser.feed(input.substring(i,i+1)); check(charParser.finish().size()==2 && charSink.text.toString().equals("前中后"));
  StringBuilder longBad=new StringBuilder("<tool_call>"); for(int i=0;i<70000;i++)longBad.append('a');longBad.append("</tool_call>tail"); Sink longSink=new Sink();DeepSeekToolBridge.StreamParser longParser=p.newParser(longSink);longParser.feed(longBad.toString());check(longParser.finish().isEmpty());check(longSink.text.toString().equals(longBad.toString()));
  Sink off=new Sink();DeepSeekToolBridge.StreamParser offParser=DeepSeekToolBridge.analyze(new JSONObject(req.toString()).put("tool_choice","none")).newParser(off);offParser.feed(input);check(offParser.finish().isEmpty()&&off.text.toString().equals(input));
  review(p, req);
  JSONObject parallel=new JSONObject(req.toString());JSONArray history=parallel.getJSONArray("messages");JSONObject second=new JSONObject(history.getJSONObject(1).getJSONArray("tool_calls").getJSONObject(0).toString()).put("id","c2");history.getJSONObject(1).getJSONArray("tool_calls").put(second);JSONObject firstResult=history.getJSONObject(2);history.put(2,new JSONObject().put("role","tool").put("tool_call_id","c2").put("content","second"));history.put(firstResult);String parallelPrompt=DeepSeekToolBridge.analyze(parallel).buildPrompt();check(parallelPrompt.contains("\"id\":\"c1\"")&&parallelPrompt.contains("\"id\":\"c2\"")&&parallelPrompt.contains("Tool result (run, id=c1): done")&&parallelPrompt.contains("Tool result (run, id=c2): second"));
  JSONObject unnamed=new JSONObject(req.toString());unnamed.getJSONArray("messages").getJSONObject(1).getJSONArray("tool_calls").getJSONObject(0).remove("id");DeepSeekToolBridge.analyze(unnamed);
  JSONObject emptyHistory=new JSONObject(req.toString());emptyHistory.getJSONArray("messages").put(new JSONObject().put("role","assistant").put("content","ordinary").put("tool_calls",new JSONArray()));DeepSeekToolBridge.analyze(emptyHistory);
  String [] malformedAttrs={"string=\"true\" string=\"false\"", "string=\"yes\"", "string=\"false\" junk"};for(String attr:malformedAttrs){String inputBad="<｜｜DSML｜｜ calls><｜｜DSML｜｜ invoke name=\"run\"><｜｜DSML｜｜ parameter name=\"x\" "+attr+">123</｜｜DSML｜｜ parameter></｜｜DSML｜｜ invoke></｜｜DSML｜｜ calls>";Sink out=new Sink();DeepSeekToolBridge.StreamParser pp=p.newParser(out);for(int j=0;j<inputBad.length();j++)pp.feed(inputBad.substring(j,j+1));check(pp.finish().isEmpty() && out.text.toString().equals(inputBad));}
  System.out.println("DeepSeekToolBridge tests passed");
 }
}
